-- 전기요금: 한국전력공사 전기요금표 (종합) (2024년 1월 1일 시행)
-- 원본: sources/electricity/2024-01-01_종합.pdf

insert into pricing.electricity_tariff_version
  (effective_from, published_label, provider, source_file,
   vat_rate, power_fund_rate, climate_charge_per_kwh, fuel_adjustment_per_kwh, note)
values
  ('2024-01-01', '2024년 1월 1일 시행', '한국전력공사', 'sources/electricity/2024-01-01_종합.pdf', 0.1, 0.037, NULL, NULL, '요금표에 종별 시행일 구분 주석 없음 — 전 종별 2024-01-01 시행')
on conflict (effective_from, source_file) do update set
  published_label = excluded.published_label,
  vat_rate = excluded.vat_rate,
  power_fund_rate = excluded.power_fund_rate,
  note = excluded.note;

-- 같은 버전의 기존 요율을 지우고 다시 넣는다 (부분 수정 시 꼬이지 않도록)
delete from pricing.electricity_rate where version_id in (
  select id from pricing.electricity_tariff_version
  where effective_from = '2024-01-01' and source_file = 'sources/electricity/2024-01-01_종합.pdf');

